#include "stdafx.h"#include "ModelMessages.h"#include <CommonRSUs.h>HANDLE HandleT(bool bHeader){  char szFile[_MAX_PATH];  strcpy_s( szFile, ::GetModel2OperatorMessagesFilePath() );  if ( bHeader )    strcat_s( szFile, ".hdr" );   //  HANDLE hHandle = ::CreateFile( szFile,                                  GENERIC_READ|GENERIC_WRITE,                                  FILE_SHARE_READ|FILE_SHARE_WRITE,//|FILE_SHARE_DELETE,                                  NULL,                                  OPEN_ALWAYS,                                  FILE_ATTRIBUTE_ARCHIVE,                                  NULL );  return hHandle;}//bool CMessagesW::OpenMessageHead(){  if ( m_pHeadT   ) return true;  //  DWORD dwSize = sizeof(CModel2OperatorMessagesHeader);  //  HANDLE hVarFile = HandleT(true);  if ( hVarFile != INVALID_HANDLE_VALUE )  {    char szName[32];    sprintf_s( szName, "Model Header Messages" );    //    m_hMapHead = ::CreateFileMapping( hVarFile, NULL, PAGE_READWRITE ,0, dwSize, szName );    if ( m_hMapHead != NULL )    {      ::CloseHandle ( hVarFile );      m_pHeadT = (CModel2OperatorMessagesHeader*)MapView( m_hMapHead, 0, dwSize );      ASS( m_pHeadT )        memset( m_pHeadT, 0, dwSize );      return true;    }  }  DWORD Err = GetLastError();  ASS(FALSE);  return false;}//bool CMessagesW::OpenMessageData(){  if ( m_hMapData ) ::CloseHandle( m_hMapData );  //  HANDLE hVarFile = HandleT(false);  if ( hVarFile != INVALID_HANDLE_VALUE )  {    char szName[32];    sprintf_s( szName, "Model Data Messages %d", m_pHeadT->dwName );    //    m_hMapData = ::CreateFileMapping( hVarFile, NULL, PAGE_READWRITE ,0, m_dwAllocKvant*(m_pHeadT->dwName+1), szName );    if ( m_hMapData != NULL )    {      ::CloseHandle ( hVarFile );      return true;    }  }  DWORD Err = GetLastError();  ASS(FALSE);  return false;}